// FONCTIONS I18N
// ============================================================

/**
 * @param {string} key
 * @param {string|null} [fallback]
 * @param {Record<string, unknown>} [vars]
 * @param {unknown} [gameRef]  si fourni, vite globalThis.game pour game.t()
 */
export function uiText(
    key: string,
    fallback: string | null = null,
    vars: Record<string, unknown> = {},
    gameRef?: import('../types/game.js').GameRuntime | null,
): string {
    let text = (fallback == null) ? key : fallback;
    const game = gameRef != null
        ? gameRef
        : ((typeof globalThis.game !== 'undefined' && globalThis.game) ? globalThis.game : null);
    if (game && typeof game.t === 'function') {
        const translated = game.t(key, vars);
        if (translated && translated !== key) text = translated;
    }
    return String(text).replace(/\{(\w+)\}/g, (_, k) => {
        const v = vars[k];
        if (v == null) return '';
        if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return String(v);
        return '';
    });
}

function resolveUiPokemonLang(gameRef: import('../types/game.js').GameRuntime | null | undefined): string {
    const runtimeGame = gameRef || ((typeof globalThis.game !== 'undefined' && globalThis.game) ? globalThis.game : null);
    return (runtimeGame && typeof runtimeGame.normalizeLanguage === 'function')
        ? runtimeGame.normalizeLanguage(runtimeGame.language)
        : 'fr';
}

/** Localized species name for plain-text sinks (textContent, Svelte `{…}`, aria-label). */
export function uiPokemonNameText(gameRef: import('../types/game.js').GameRuntime | null | undefined, name: string): string {
    const raw = String(name || '');
    if (!raw) return raw;
    return localizePokemonName(raw, resolveUiPokemonLang(gameRef));
}

// Defense-in-depth XSS (cf. AUDIT_SECURITE.md §2) : la valeur retournee est
// systematiquement injectee via innerHTML par les appelants. Si le nom n'est
// pas dans la table de localisation (cas d'une save importee piegee), on
// passe par escapeHtml. Les noms FR/EN connus ne contiennent aucun caractere
// a echapper, donc l'echappement est neutre pour le rendu normal.
export function uiPokemonName(gameRef: import('../types/game.js').GameRuntime | null | undefined, name: string): string {
    const raw = String(name || '');
    if (!raw) return raw;
    return escapeHtml(uiPokemonNameText(gameRef, raw));
}

export function uiDataText(
    gameRef: GameRuntime | null | undefined,
    category: string,
    key: string,
    field: string,
    fallback: string,
): string {
    if (category === 'upgrades' && key === 'respawn' && field === 'effect') {
        const ms = balanceRespawnUpgradeMsPerLevel();
        const lang = (gameRef && typeof gameRef.normalizeLanguage === 'function')
            ? gameRef.normalizeLanguage(gameRef.language)
            : 'fr';
        return lang === 'en' ? `-${ms} ms per level` : `-${ms} ms par niveau`;
    }
    const lang = (gameRef && typeof gameRef.normalizeLanguage === 'function')
        ? gameRef.normalizeLanguage(gameRef.language)
        : 'fr';
    if (lang !== 'en') {
        if (category === 'pokeMart') {
            const frEntry = POKE_MART_I18N_FR[key];
            const frValue = frEntry?.[field as 'name' | 'description'];
            if (typeof frValue === 'string' && frValue.length > 0) return frValue;
        }
        return fallback;
    }
    const categoryMap = UI_DATA_I18N_EN[category as I18nDataCategory];
    if (!categoryMap || !(key in categoryMap)) return fallback;
    const entry = categoryMap[key as keyof typeof categoryMap] as Record<string, string> | undefined;
    const value = entry?.[field];
    return (typeof value === 'string' && value.length > 0) ? value : fallback;
}

export function uiTitleCaseFromKeyEn(key: string): string {
    return String(key || '')
        .replace(/^ct_/i, '')
        .split(/[_\s-]+/)
        .filter(Boolean)
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
}

export function uiItemStatLabelEn(stat: string): string {
    if (stat === 'hp') return 'HP';
    if (stat === 'attack') return 'ATK';
    if (stat === 'defense') return 'DEF';
    if (stat === 'speed') return 'SPD';
    if (stat === 'spattack') return 'Sp. Atk';
    if (stat === 'spdefense') return 'Sp. Def';
    if (stat === 'all') return 'all stats';
    return stat || 'stats';
}

export function uiFormatItemEffectDescriptionEn(item: UiItemLike | null | undefined, key: string): string {
    if (!item || !item.effect || typeof item.effect !== 'object') {
        if (item && item.evolutionItem === true) return 'Evolution item for specific species.';
        if (typeof key === 'string' && key.endsWith('_stone')) return 'Evolves specific species.';
        return '';
    }

    const effect = item.effect;
    if (effect.type === 'timeDust' && Number(effect.hours) > 0) {
        return `Instantly grants ${Number(effect.hours)}h of passive stat gains.`;
    }
    if (effect.type === 'instantEggHatch') {
        const rarityRaw = String(effect.eggRarity || '').toLowerCase();
        const rarityLabel = rarityRaw ? (rarityRaw.charAt(0).toUpperCase() + rarityRaw.slice(1)) : 'matching';
        return `Instantly opens 1 ${rarityLabel} egg from inventory.`;
    }

    if (effect.type === 'timedGlobalBoost' && String(effect.boostType || '').startsWith('passiveGain_')) {
        const statKey = String(effect.boostType).slice('passiveGain_'.length);
        const stat = uiItemStatLabelEn(statKey);
        const durationMs = Number(effect.duration);
        const minutes = Math.max(1, Math.round(durationMs / 60000));
        const mult = Math.max(2, Math.round(1 + (Number(effect.value) || 0)));
        return `Multiplies ${stat} passive gain/sec by x${mult} for ${minutes} min (reuse adds time).`;
    }

    const stat = uiItemStatLabelEn(effect.stat || 'all');
    const value = Number(effect.value);
    const hasValue = Number.isFinite(value) && value > 0;
    const percent = hasValue ? Math.round(value * 1000) / 10 : 0;
    const durationMs = Number(effect.duration);
    const hasDuration = Number.isFinite(durationMs) && durationMs > 0;

    if (hasValue && hasDuration) {
        const minutes = Math.max(1, Math.round(durationMs / 60000));
        if (stat === 'all stats') return `Temporarily increases all stats by +${percent}% for ${minutes} min.`;
        return `Temporarily increases ${stat} by +${percent}% for ${minutes} min.`;
    }
    if (hasValue && effect.duration === null) {
        if (stat === 'all stats') return `Permanently increases all passive stat gains by +${percent}%.`;
        return `Permanently increases ${stat} passive gains by +${percent}%.`;
    }
    if (item.evolutionItem === true) return 'Evolution item for specific species.';
    if (typeof key === 'string' && key.endsWith('_stone')) return 'Evolves specific species.';
    return '';
}

export function uiItemDisplayNameEn(item: UiItemLike | null | undefined, key: string, fallback: string): string {
    const mapped = UI_ITEM_MAP[key];
    if (mapped && typeof mapped.name === 'string' && mapped.name.length > 0) return mapped.name;
    if (item && item.evolutionItem === true && key === 'metal_coat') return 'Metal Coat';
    const generated = uiTitleCaseFromKeyEn(key);
    return generated || fallback || key || 'Item';
}

export function uiItemDisplayDescriptionEn(item: UiItemLike | null | undefined, key: string, fallback: string): string {
    const mapped = UI_ITEM_MAP[key];
    if (mapped && mapped.description) return mapped.description;

    if (key === 'metal_coat') {
        const hasEvo = !!(item && item.evolutionItem === true);
        const hasHeld = !!(item && item.effect && item.effect.type_damage_bonus);
        if (hasEvo && hasHeld) {
            return 'Evolves certain species (Scyther, Onix…). When held: +15% Steel-type attack damage.';
        }
        if (hasEvo) return 'Evolution item for specific species.';
        if (hasHeld) return '+15% Steel-type attack damage.';
    }

    const fromEffect = uiFormatItemEffectDescriptionEn(item, key);
    return fromEffect || fallback || '';
}

function uiExtractCtMoveSource(item: UiItemLike | null | undefined, key: string, fallback: string): string {
    if (item && typeof item.moveName === 'string' && item.moveName.trim()) {
        return item.moveName.trim();
    }
    if (item && typeof item.name === 'string' && item.name.trim()) {
        return item.name.replace(/^CT\s*/i, '').trim();
    }
    if (typeof key === 'string' && key.startsWith('ct_')) {
        return key.slice(3).replace(/_/g, ' ').trim();
    }
    if (typeof fallback === 'string') {
        return fallback.replace(/^CT\s*/i, '').trim();
    }
    return '';
}

function uiEnglishMoveDisplayName(moveSource: string): string {
    const raw = String(moveSource || '').trim();
    if (!raw) return '';
    const resolved = resolveMoveName(raw);
    const db = MOVES_DB as Record<string, { name?: string }>;
    const frDisplay = (db && db[resolved] && db[resolved].name) ? String(db[resolved].name) : resolved;
    return localizeMoveName(frDisplay, 'en');
}

export function uiCtDisplayNameEn(item: UiItemLike | null | undefined, key: string, fallback: string): string {
    const source = uiExtractCtMoveSource(item, key, fallback);
    const enMove = uiEnglishMoveDisplayName(source);
    return enMove ? `TM ${enMove}` : (fallback || 'TM');
}

export function uiCtDisplayDescriptionEn(item: UiItemLike | null | undefined, key: string): string {
    const source = uiExtractCtMoveSource(item, key, '');
    const enMove = uiEnglishMoveDisplayName(source);
    return enMove ? `Teaches ${enMove}.` : 'Teaches a move.';
}

export function uiIsEn(gameRef: GameRuntime | null | undefined): boolean {
    return !!(gameRef && typeof gameRef.normalizeLanguage === 'function' && gameRef.normalizeLanguage(gameRef.language) === 'en');
}

export function uiMaybeLocalizeCtName(
    gameRef: GameRuntime | null | undefined,
    item: UiItemLike | null | undefined,
    key: string,
    fallbackName: string,
): string {
    if (!uiIsEn(gameRef) || typeof key !== 'string' || !key.startsWith('ct_')) return fallbackName;
    return uiCtDisplayNameEn(item, key, fallbackName);
}

export function uiMaybeLocalizeCtDescription(
    gameRef: GameRuntime | null | undefined,
    item: UiItemLike | null | undefined,
    key: string,
    fallbackDescription: string,
): string {
    if (!uiIsEn(gameRef) || typeof key !== 'string' || !key.startsWith('ct_')) return fallbackDescription;
    return uiCtDisplayDescriptionEn(item, key);
}

export function uiMaybeLocalizeItemName(
    gameRef: GameRuntime | null | undefined,
    item: UiItemLike | null | undefined,
    key: string,
    fallbackName: string,
): string {
    if (uiIsEn(gameRef)) {
        if (typeof key === 'string' && key.startsWith('ct_')) return uiCtDisplayNameEn(item, key, fallbackName);
        return uiItemDisplayNameEn(item, key, fallbackName);
    }
    const frMapped = UI_ITEM_I18N_FR[key];
    if (frMapped && frMapped.name) return frMapped.name;
    return fallbackName;
}

export function uiMaybeLocalizeItemDescription(
    gameRef: GameRuntime | null | undefined,
    item: UiItemLike | null | undefined,
    key: string,
    fallbackDescription: string,
): string {
    if (uiIsEn(gameRef)) {
        if (typeof key === 'string' && key.startsWith('ct_')) return uiCtDisplayDescriptionEn(item, key);
        return uiItemDisplayDescriptionEn(item, key, fallbackDescription);
    }
    const frMapped = UI_ITEM_I18N_FR[key];
    if (frMapped && frMapped.description) return frMapped.description;
    return fallbackDescription;
}

export function getLocalizedItemNameUI(
    gameRef: GameRuntime | null | undefined,
    itemKey: string,
    itemDef: UiItemLike | null | undefined,
    fallbackName: string,
): string {
    return uiMaybeLocalizeItemName(gameRef, itemDef || {}, itemKey, fallbackName);
}

/** Localized display name for a held item key (EN via UI_ITEM_I18N_EN, FR via HELD_ITEMS). */
export function getLocalizedHeldItemLabel(
    gameRef: GameRuntime | null | undefined,
    itemKey: string,
): string {
    const key = String(itemKey || '').trim();
    if (!key) return '';
    const itemDef = (HELD_ITEMS as Record<string, UiItemLike>)[key];
    const fallbackName = itemDef?.name || key;
    return getLocalizedItemNameUI(gameRef, key, itemDef, fallbackName);
}

/** Localized description for a held item key (EN via UI_ITEM_I18N_EN, FR via HELD_ITEMS). */
export function getLocalizedHeldItemDescription(
    gameRef: GameRuntime | null | undefined,
    itemKey: string,
): string {
    const key = String(itemKey || '').trim();
    if (!key) return '';
    const itemDef = (HELD_ITEMS as Record<string, UiItemLike>)[key];
    const fallbackDescription = itemDef?.description || '';
    return uiMaybeLocalizeItemDescription(gameRef, itemDef, key, fallbackDescription);
}

export function getLocalizedShopDataTextUI(
    gameRef: GameRuntime | null | undefined,
    category: string,
    key: string,
    field: string,
    fallback: string,
): string {
    const base = uiDataText(gameRef, category, key, field, fallback);
    if (!uiIsEn(gameRef)) return base;
    if (category === 'tokenShop' && typeof key === 'string' && key.startsWith('ct_')) {
        if (field === 'name') return uiCtDisplayNameEn(null, key, base || fallback);
        if (field === 'description') return uiCtDisplayDescriptionEn(null, key);
    }
    return base;
}
